// This file is generated by AI.

// 预览静态站点的缓存身份。
//
// 不变量: **缓存按「项目 + 引擎」记账**。`add_static_site` 把项目根与引擎目录记在一个 siteId 名下,
// 只判断"url 有没有值"就早退的话, 换项目时会原样返回上一个项目的站点 —— iframe 加载的是旧项目
// (所以画面正常、能交互), 而 `previewSiteId` 与活动会话都没更新, 工具条一直显示"未连接"。

import { beforeEach, describe, expect, it, vi } from 'vitest';

const mocks = vi.hoisted(() => ({
  addStaticSite: vi.fn(),
  setPreview: vi.fn(),
  startPreviewServer: vi.fn(),
}));

vi.mock('../src/commands/server', () => ({
  addStaticSite: mocks.addStaticSite,
  copyDirectory: vi.fn(),
  moveToTrash: vi.fn(),
  sendPreviewCommand: vi.fn(),
  setActivePreviewSession: vi.fn(),
  setEmbeddedPreviewLaunchId: vi.fn(),
  setPreviewMuted: vi.fn(),
  startLspServer: vi.fn(),
  startPreviewServer: mocks.startPreviewServer,
}));

vi.mock('../src/state/store.svelte', () => ({
  useAppStore: {
    getState: () => ({
      applyLivePreviewEvent: vi.fn(),
      beginLivePreview: vi.fn(),
      livePreviewMarker: null,
      setPreview: mocks.setPreview,
    }),
  },
}));

import { previewClient } from '../src/preview/client';

describe('previewClient.ensureSite 的缓存身份', () => {
  beforeEach(() => {
    let counter = 0;
    mocks.addStaticSite.mockReset();
    mocks.addStaticSite.mockImplementation(async () => `site-${++counter}`);
    mocks.setPreview.mockReset();
    mocks.startPreviewServer.mockReset();
    mocks.startPreviewServer.mockImplementation(async () => 'http://127.0.0.1:8899/');
    previewClient.resetSite();
  });

  it('同一个项目重复调用只注册一次 (拨开关/改设置不该重挂站点)', async () => {
    await previewClient.ensureSite('C:/games/alpha');
    await previewClient.ensureSite('C:/games/alpha');
    expect(mocks.addStaticSite).toHaveBeenCalledTimes(1);
  });

  it('换项目必须重新注册, 并返回新站点的 url', async () => {
    const first = await previewClient.ensureSite('C:/games/alpha');
    const second = await previewClient.ensureSite('C:/games/beta');
    expect(mocks.addStaticSite).toHaveBeenCalledTimes(2);
    expect(first).not.toBe(second);
    expect(second).toContain('site-2');
  });

  it('同一项目换引擎要重新注册 (站点绑定的是"项目 + 引擎")', async () => {
    await previewClient.ensureSite('C:/games/alpha', 'C:/engines/v1');
    await previewClient.ensureSite('C:/games/alpha', 'C:/engines/v2');
    expect(mocks.addStaticSite).toHaveBeenCalledTimes(2);
  });

  it('同一路径的不同写法算同一个项目 (大小写 / 分隔符 / 尾斜杠)', async () => {
    await previewClient.ensureSite('C:\\Games\\Alpha\\');
    await previewClient.ensureSite('c:/games/alpha');
    expect(mocks.addStaticSite).toHaveBeenCalledTimes(1);
  });

  it('重新注册时把新的 siteId 写回 store (网关靠它认领会话)', async () => {
    await previewClient.ensureSite('C:/games/alpha');
    await previewClient.ensureSite('C:/games/beta');
    expect(mocks.setPreview).toHaveBeenCalledTimes(2);
    const last = mocks.setPreview.mock.calls.at(-1)?.[0] as { previewSiteId: string };
    expect(last.previewSiteId).toBe('site-2');
  });

  it('命中缓存时也要把 siteId 写回 store (重新打开同一个项目: setProject 刚清空过它)', async () => {
    await previewClient.ensureSite('C:/games/alpha');
    mocks.setPreview.mockClear();
    await previewClient.ensureSite('C:/games/alpha');
    // 没有再注册站点, 但会话信息必须补回来
    expect(mocks.addStaticSite).toHaveBeenCalledTimes(1);
    expect(mocks.setPreview).toHaveBeenCalledTimes(1);
    const payload = mocks.setPreview.mock.calls[0]?.[0] as { previewSiteId: string };
    expect(payload.previewSiteId).toBe('site-1');
  });

  it('resetSite 之后重新注册', async () => {
    await previewClient.ensureSite('C:/games/alpha');
    previewClient.resetSite();
    await previewClient.ensureSite('C:/games/alpha');
    expect(mocks.addStaticSite).toHaveBeenCalledTimes(2);
  });
});
